public static MZNAG_CustomerStatusBatchController construct()
{
    MZNAG_CustomerStatusBatchController controller = new MZNAG_CustomerStatusBatchController();
    controller.parmClassName(classStr(MZNAG_CustomerStatusBatchService));
    controller.parmMethodName(methodStr(MZNAG_CustomerStatusBatchService, processOperation));
    controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
    controller.parmDialogCaption("Update customer status");
    return controller;
}

public ClassDescription caption()
{
    return "Update customer status for sales orders";
}

public static void main(Args _args)
{
    MZNAG_CustomerStatusBatchController controller = MZNAG_CustomerStatusBatchController::construct();

    controller.startOperation();
}
